          category: "saving",
          date: (sg.updatedAt ? new Date(sg.updatedAt) : now).toISOString().split("T")[0],
          icon: "PiggyBank",
          metricValue: `${sg.currentAmount.toLocaleString("vi-VN")} \u20AB`,
          metricLabel: "\u0110\xE3 t\xEDch l\u0169y",
