  const titleWithoutExt = import_path.default.basename(baseName, import_path.default.extname(baseName)).normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-zA-Z0-9_-]/g, "_").substring(0, 50);
  const randomHash = import_crypto4.default.randomBytes(6).toString("hex");
