    if (repetitionCount === 1) return 1;
    if (repetitionCount === 2 || lapses > 2) return 2;
    if (intervalDays >= 30 && repetitionCount >= 5) return 5;
    if (intervalDays >= 14 && repetitionCount >= 4) return 4;
