apiRouter.get("/global-chat/stream", (req, res) => {
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache, no-transform");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("X-Accel-Buffering", "no");
  if (typeof res.flushHeaders === "function") {
    res.flushHeaders();
  }
  res.write(`event: online_count
data: ${JSON.stringify({ count: globalChatService.getOnlineCount() })}

`);
  const unsubscribe = globalChatService.subscribe((data) => {
    try {
      res.write(`event: ${data.event}
data: ${JSON.stringify(data.payload)}

`);
    } catch {
    }
  });
  req.on("close", () => {
    unsubscribe();
    res.end();
  });
});
