apiRouter.post("/focus/complete", async (req, res) => {
  const userId2 = req.userId;
  const { title, mode, plannedDuration, actualDuration, taskId, subjectId } = req.body;
  const prisma = getPrisma();
  try {
    const requestedMins = parseFloat(actualDuration) || parseFloat(plannedDuration) || 25;
    if (isNaN(requestedMins) || requestedMins <= 0 || requestedMins > 180) {
      res.status(400).json({
        success: false,
        error: { code: "INVALID_DURATION", message: "Th\u1EDDi l\u01B0\u1EE3ng t\u1EADp trung kh\xF4ng h\u1EE3p l\u1EC7 (t\u1ED1i thi\u1EC3u 1 ph\xFAt, t\u1ED1i \u0111a 180 ph\xFAt)." },
        message: "Th\u1EDDi l\u01B0\u1EE3ng t\u1EADp trung kh\xF4ng h\u1EE3p l\u1EC7 (t\u1ED1i thi\u1EC3u 1 ph\xFAt, t\u1ED1i \u0111a 180 ph\xFAt)."
      });
      return;
    }
    const recentSession = await prisma.focusSession.findFirst({
      where: { userId: userId2, status: "Completed" },
      orderBy: { createdAt: "desc" }
    });
    if (recentSession && Date.now() - new Date(recentSession.createdAt).getTime() < 3e4) {
      res.status(429).json({
        success: false,
        error: { code: "TOO_FREQUENT", message: "B\u1EA1n \u0111ang ghi nh\u1EADn phi\xEAn t\u1EADp trung qu\xE1 nhanh. Vui l\xF2ng ho\xE0n th\xE0nh phi\xEAn th\u1EF1c t\u1EBF tr\u01B0\u1EDBc khi g\u1EEDi." },
        message: "B\u1EA1n \u0111ang ghi nh\u1EADn phi\xEAn t\u1EADp trung qu\xE1 nhanh. Vui l\xF2ng ho\xE0n th\xE0nh phi\xEAn th\u1EF1c t\u1EBF tr\u01B0\u1EDBc khi g\u1EEDi."
      });
      return;
    }
    const durationMins = requestedMins;
    const durationHours = durationMins / 60;
    const session = await prisma.focusSession.create({
      data: {
        userId: userId2,
        title: title || "Phi\xEAn t\u1EADp trung",
        mode: mode || "Pomodoro",
        status: "Completed",
        plannedDuration: parseFloat(plannedDuration) || 25,
        actualDuration: durationMins,
        startTime: (/* @__PURE__ */ new Date()).toISOString()
      }
    });
    if (taskId) {
      const task = await prisma.task.findFirst({ where: { id: taskId, userId: userId2 } });
      if (task) {
        await prisma.task.update({
          where: { id: taskId },
          data: { actualHours: { increment: durationHours } }
        });
      }
    }
    if (subjectId) {
      const subject = await prisma.subject.findFirst({ where: { id: subjectId, userId: userId2 } });
      if (subject) {
        await prisma.studySession.create({
          data: {
            userId: userId2,
            subjectId,
            durationMinutes: Math.round(durationMins),
            date: (/* @__PURE__ */ new Date()).toISOString().split("T")[0],
            notes: `Phi\xEAn t\u1EADp trung: ${session.title}`
          }
        });
      }
    }
    await AutomationEngineService.triggerEvent(userId2, "focus.completed", {
      sessionId: session.id,
      durationMinutes: durationMins
    });
    res.json({ success: true, session });
  } catch (err) {
    res.status(500).json({
      success: false,
      error: { code: "FOCUS_ERROR", message: err.message },
      message: err.message
    });
  }
});
