connectRouter.get("/messages/stream", requireAuth, (req, res) => {
  const userId2 = req.userId;
  res.setHeader("Content-Type", "text/event-stream");
  res.setHeader("Cache-Control", "no-cache, no-transform");
  res.setHeader("Connection", "keep-alive");
  res.setHeader("X-Accel-Buffering", "no");
  res.flushHeaders?.();
  res.write(`data: ${JSON.stringify({ event: "connected", payload: { userId: userId2 } })}

`);
  const unsubscribe = ConnectMessagingService.subscribeUser(userId2, (data) => {
    try {
      res.write(`data: ${JSON.stringify(data)}

`);
    } catch {
    }
  });
  const keepAlive = setInterval(() => {
    try {
      res.write(": ping\n\n");
    } catch {
    }
  }, 25e3);
  req.on("close", () => {
    clearInterval(keepAlive);
    unsubscribe();
  });
});
