widgetRouter.post("/complete-top-task", async (req, res) => {
  try {
    const user = await authenticateWidgetUser(req);
    if (!user) {
      res.status(401).json({
        success: false,
        error: { code: "UNAUTHORIZED", message: "Y\xEAu c\u1EA7u \u0111\u0103ng nh\u1EADp \u0111\u1EC3 ho\xE0n th\xE0nh c\xF4ng vi\u1EC7c." },
        message: "Y\xEAu c\u1EA7u \u0111\u0103ng nh\u1EADp \u0111\u1EC3 ho\xE0n th\xE0nh c\xF4ng vi\u1EC7c."
      });
      return;
    }
    const prisma = getPrisma();
    const explicitTaskId = req.body?.taskId;
    let targetTask = null;
    if (explicitTaskId) {
      targetTask = await prisma.task.findFirst({
        where: { id: explicitTaskId, userId: user.id, deletedAt: null }
      });
    }
    if (!targetTask) {
      const todayStr = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
      const activeTasks = await prisma.task.findMany({
        where: {
          userId: user.id,
          deletedAt: null,
          status: { notIn: ["Ho\xE0n th\xE0nh", "Completed", "Done", "H\u1EE7y", "Cancelled"] }
        },
        orderBy: [
          { createdAt: "desc" }
        ]
      });
      if (activeTasks.length > 0) {
        activeTasks.sort((a, b) => getPriorityScore(b.priority) - getPriorityScore(a.priority));
        targetTask = activeTasks[0];
      }
    }
    if (!targetTask) {
      res.json({
        success: false,
        message: "Kh\xF4ng c\xF3 c\xF4ng vi\u1EC7c n\xE0o \u0111ang ch\u1EDD \u0111\u1EC3 ho\xE0n th\xE0nh h\xF4m nay."
      });
      return;
    }
    const updated = await prisma.task.update({
      where: { id: targetTask.id },
      data: { status: "Ho\xE0n th\xE0nh" }
    });
    try {
      await progressionService.awardXp(user.id, {
        amount: 20,
        category: "task",
        source: "widget_lockscreen",
        sourceId: updated.id,
        description: `Ho\xE0n th\xE0nh vi\u1EC7c t\u1EEB m\xE0n h\xECnh kh\xF3a: ${updated.title}`
      });
    } catch (xpErr) {
      console.warn("XP award notice:", xpErr);
    }
    res.json({
      success: true,
      message: `\u0110\xE3 ho\xE0n th\xE0nh: "${updated.title}"! B\xE9 Lumi ch\xFAc m\u1EEBng b\u1EA1n \u{1F389}`,
      completedTask: {
        id: updated.id,
        title: updated.title,
        status: updated.status
      }
    });
  } catch (error) {
    console.error("Error completing top task from widget:", error);
    res.status(500).json({
      success: false,
      error: { code: "SERVER_ERROR", message: error.message },
      message: error.message
    });
  }
});

